"""Regenerate independently authored synthetic examples; no source data or network."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SEED = 'autoclick-public-examples-v1'
OUTPUTS = {'examples/index.html': '<!doctype html>\n<html lang="zh-CN">\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>AutoClick · Synthetic Demo</title>\n<style>\n  body { max-width: 760px; margin: 48px auto; padding: 0 24px; font: 18px/1.6 system-ui, sans-serif; color: #183e38; background: #f6f8f6; }\n  article { margin: 24px 0; padding: 24px; border: 1px solid #b5c8c1; border-radius: 12px; background: white; }\n  button { font: inherit; padding: 10px 18px; cursor: pointer; }\n  output { display: block; padding-top: 12px; }\n  small { color: #45645d; }\n</style>\n<h1>AutoClick 合成演示 / Synthetic demo</h1>\n<p>所有名称、编号和状态都是新建测试数据，无品牌、客户、订单、账号或外部请求。</p>\n<p>All names, identifiers and states are invented. No account or production service is used.</p>\n<article class="product-row" data-product-id="synthetic-item-a">\n  <h2 class="product-name">Demo Item A</h2>\n  <button id="count-button" type="button"><span>记录一次 / Count once</span></button>\n  <output id="count" aria-live="polite">0</output>\n</article>\n<article class="product-row" data-product-id="synthetic-item-b">\n  <h2 class="product-name">Demo Item B</h2>\n  <div id="toggle-slot"><button id="toggle-button" type="button">讲解</button></div>\n  <output id="toggle-count" aria-live="polite">DOM clicks: 0</output>\n  <small>Desktop controlled-toggle example: the button is replaced after each click. A successful scheduled round leaves it at “取消讲解”.</small>\n</article>\n<p>先在扩展或桌面工具中选择按钮，再设置至少 1 秒的间隔。停止后再切换目标。<br>Choose a button in AutoClick, set an interval of at least one second, and stop before selecting another target.</p>\n<script src="demo.js"></script>\n</html>\n', 'examples/demo.js': "'use strict';\n\nlet count = 0;\nlet toggleCount = 0;\ndocument.getElementById('count-button').addEventListener('click', () => {\n  document.getElementById('count').textContent = String(++count);\n});\ndocument.getElementById('toggle-slot').addEventListener('click', (event) => {\n  if (!event.target.closest('button')) return;\n  const current = document.getElementById('toggle-button');\n  const replacement = document.createElement('button');\n  replacement.id = 'toggle-button';\n  replacement.type = 'button';\n  replacement.textContent = current.textContent === '讲解' ? '取消讲解' : '讲解';\n  current.replaceWith(replacement);\n  document.getElementById('toggle-count').textContent = `DOM clicks: ${++toggleCount}`;\n});\n"}

if __name__ == '__main__':
    for relative, text in OUTPUTS.items():
        target = ROOT / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding='utf-8')
    print(f'Regenerated {len(OUTPUTS)} fixed synthetic examples; seed={SEED}')
